local buckets={}
for _,ring in ipairs(rings)do
  for i=2,#ring do
    local a,b=ring[i-1],ring[i]
    local edge={a[1],a[2],b[1],b[2]}
    for k=math.floor(math.min(a[2],b[2])*100),math.floor(math.max(a[2],b[2])*100)do
      local bucket=buckets[k]or{};buckets[k]=bucket;bucket[#bucket+1]=edge
    end
  end
end
rings=nil
local M={}
function M.contains(lat,lon)
  if type(lat)~='number'or type(lon)~='number'or lat~=lat or lon~=lon or lat<50 or lat>54 or lon<3 or lon>8 then return false end
  local inside=false
  for _,e in ipairs(buckets[math.floor(lat*100)]or{})do
    local ax,ay,bx,by=e[1],e[2],e[3],e[4]
    if lat>=math.min(ay,by)and lat<=math.max(ay,by)and lon>=math.min(ax,bx)and lon<=math.max(ax,bx)and math.abs((lon-ax)*(by-ay)-(lat-ay)*(bx-ax))<1e-12 then return true end
    if (ay>lat)~=(by>lat)and lon<(bx-ax)*(lat-ay)/(by-ay)+ax then inside=not inside end
  end
  return inside
end
return M
